INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '预检技能与运行环境','ai:agent:preflight:api','api',p.id,'/v1/agent-console/agents/{id}/preflight','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:agent:preflight:api' AND del_flag=0);
